/**
 * @param {params} params
 * @param {api} params.api
 * @param {any} params.event
 */
function evaluateEvent({
    api,
    event
}) {
    if (!event.payload.isInitialPageLoad) {
        return {
            event: "Selected Dashboard Tab",
            value: {
                tab: event.payload.selectedTabLabel
            }
        };
    }
}

/**
* @param {params} params
* @param {api} params.api
* @param {any} params.event
*/
function evaluateEvent({api, event}) {
	if (!event.payload.isInitialPageLoad) {
		var parentTab = event.payload.selectedTab;
		var selectedTabValue;

		//Scheduled Jobs doesn't have subtabs so we can skip
		if (parentTab.indexOf("scheduled_jobs") !== -1) {
			selectedTabValue = parentTab;
		} else {
			//For System events monitoring, add the subtab to the url if its saved
			if (api.state.selected_events_tab) {
				selectedTabValue = parentTab + "_" + api.state.selected_events_tab;
			} else {
				selectedTabValue = parentTab;
			}
		}

		return {
			params: {
				"selectedTab": selectedTabValue
			}
		};
	}
}

