/**
 * @param {params} params
 * @param {api} params.api
 * @param {any} params.event
 */
function evaluateEvent({
    api,
    event
}) {
    var queueName = api.context.props.queue;
    var eventName = api.context.props.event;
    var end = api.context.props.end;
    var start = api.context.props.start;
    var diffInHours = -1;

    if (queueName == undefined || queueName == null)
        queueName = "empty";

    if (eventName == undefined || eventName == null)
        eventName = "empty";

    if (end != undefined && end != null) {
        var end_date = new Date(end);
        var start_date = new Date(start);
        diffInHours = Math.round(Math.abs(end_date - start_date) / 3.6e6);
    }

    return {
        event: "Apply Filter - System Event Monitoring",
        value: {
            queue: queueName,
            event: eventName,
            intervalDiffInHours: diffInHours
        }
    };
}

